<script setup lang="ts">
import { useI18n } from 'vue-i18n'
import type { PaymentOrder } from '@/features/monitor/monitorModel'
import { formatDate } from '@/features/monitor/monitorViewModel'
type PaymentOrdersFilter = { status: string; channel: string; planCode: string; email: string }
const props = defineProps<{ items: PaymentOrder[]; total: number; page: number; totalPages: number; loading: boolean; filters: PaymentOrdersFilter; detail: PaymentOrder | null; detailLoading: boolean }>()
const emit = defineEmits<{ refresh: []; detail: [orderNo: string]; 'close-detail': []; 'go-page': [page: number]; 'mark-paid': [orderNo: string]; close: [orderNo: string] }>()
const { t } = useI18n()
const updateFilters = (field: keyof PaymentOrdersFilter, value: string) => {
  // eslint-disable-next-line vue/no-mutating-props -- filters 为父组件传入的草稿对象，此处为受控表单的有意回写
  props.filters[field] = value
}
</script>
<template>
  <section class="glass-card p-5 space-y-4">
    <div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-lg font-semibold">{{ t('monitor.paymentOrders.title') }}</h2><p class="monitor-caption text-sm">{{ t('monitor.paymentOrders.hint') }}</p></div><button class="monitor-btn-secondary" :disabled="loading" @click="emit('refresh')">{{ t('common.refresh') }}</button></div>
    <div class="grid gap-3 sm:grid-cols-4"><input :value="filters.email" class="monitor-input" :placeholder="t('monitor.paymentOrders.email')" @input="updateFilters('email', ($event.target as HTMLInputElement).value)" /><input :value="filters.planCode" class="monitor-input" :placeholder="t('monitor.paymentOrders.plan')" @input="updateFilters('planCode', ($event.target as HTMLInputElement).value)" /><input :value="filters.channel" class="monitor-input" :placeholder="t('monitor.paymentOrders.channel')" @input="updateFilters('channel', ($event.target as HTMLInputElement).value)" /><select :value="filters.status" class="monitor-input" @change="updateFilters('status', ($event.target as HTMLSelectElement).value)"><option value="">{{ t('monitor.paymentOrders.allStatuses') }}</option><option value="pending">pending</option><option value="paid">paid</option><option value="closed">closed</option><option value="expired">expired</option></select></div>
    <div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr class="text-left"><th>{{ t('monitor.paymentOrders.order') }}</th><th>{{ t('monitor.paymentOrders.email') }}</th><th>{{ t('monitor.paymentOrders.plan') }}</th><th>{{ t('monitor.paymentOrders.amount') }}</th><th>{{ t('monitor.paymentOrders.status') }}</th><th>{{ t('monitor.paymentOrders.created') }}</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.order_no" class="border-t border-[var(--rule)]"><td class="font-mono"><button class="underline" @click="emit('detail', item.order_no)">{{ item.order_no }}</button></td><td>{{ item.email || '—' }}</td><td>{{ item.plan_code }}</td><td>{{ (item.amount_cents / 100).toFixed(2) }} {{ item.currency }}</td><td>{{ item.status }}</td><td>{{ formatDate(item.created_at) }}</td><td class="whitespace-nowrap"><button v-if="item.status === 'pending'" class="monitor-btn-secondary mr-2" @click="emit('mark-paid', item.order_no)">{{ t('monitor.paymentOrders.markPaid') }}</button><button v-if="item.status === 'pending'" class="monitor-btn-secondary" @click="emit('close', item.order_no)">{{ t('monitor.paymentOrders.close') }}</button></td></tr><tr v-if="!items.length"><td colspan="7" class="py-8 text-center monitor-caption">{{ t('monitor.paymentOrders.empty') }}</td></tr></tbody></table></div>
    <div v-if="detail || detailLoading" class="rounded border border-[var(--rule)] p-4 space-y-2"><div class="flex justify-between"><h3 class="font-semibold">{{ t('monitor.paymentOrders.detail') }}</h3><button class="monitor-btn-secondary" @click="emit('close-detail')">{{ t('monitor.paymentOrders.closeDetail') }}</button></div><p v-if="detailLoading" class="monitor-caption">{{ t('common.loading') }}</p><template v-else-if="detail"><p class="font-mono">{{ detail.order_no }} · {{ detail.email || '—' }}</p><p>{{ detail.status }} · {{ detail.channel }} · {{ (detail.amount_cents / 100).toFixed(2) }} {{ detail.currency }}</p><p class="text-xs whitespace-pre-wrap break-all">{{ detail.callback_payload || t('monitor.paymentOrders.noCallback') }}</p></template></div>
    <div class="flex items-center justify-between text-sm"><span>{{ t('monitor.pageSummary', { page, totalPages, total }) }}</span><div class="flex gap-2"><button class="monitor-btn-secondary" :disabled="page <= 1" @click="emit('go-page', page - 1)">{{ t('monitor.previous') }}</button><button class="monitor-btn-secondary" :disabled="page >= totalPages" @click="emit('go-page', page + 1)">{{ t('monitor.next') }}</button></div></div>
  </section>
</template>
